model_r2 &lt;- function(data, predictors) {
  if (length(predictors) == 0) {
    return(0)
  }

  fit &lt;- lm(reformulate(predictors, response = "satisfaction"), data = data)
  summary(fit)$r.squared
}

shapley_r2 &lt;- function(data, predictors) {
  p &lt;- length(predictors)
  n_masks &lt;- bitwShiftL(1L, p)
  r2_cache &lt;- numeric(n_masks)

  popcount &lt;- function(mask) {
    sum(as.integer(intToBits(mask))[seq_len(p)])
  }

  for (mask in 0:(n_masks - 1L)) {
    bits &lt;- as.logical(sapply(
      0:(p - 1L),
      function(j) bitwAnd(mask, bitwShiftL(1L, j)) != 0L
    ))
    r2_cache[mask + 1L] &lt;- model_r2(data, predictors[bits])
  }

  values &lt;- setNames(numeric(p), predictors)

  for (j in seq_len(p)) {
    bit &lt;- bitwShiftL(1L, j - 1L)

    for (mask in 0:(n_masks - 1L)) {
      if (bitwAnd(mask, bit) == 0L) {
        subset_size &lt;- popcount(mask)
        weight &lt;- factorial(subset_size) *
          factorial(p - subset_size - 1L) /
          factorial(p)

        values[j] &lt;- values[j] +
          weight * (r2_cache[mask + bit + 1L] - r2_cache[mask + 1L])
      }
    }
  }

  values
}

johnson_relative_weights &lt;- function(data, outcome, predictors) {
  x &lt;- scale(data[, predictors])
  y &lt;- as.numeric(scale(data[[outcome]]))

  predictor_cor &lt;- cor(x)
  outcome_cor &lt;- as.numeric(cor(x, y))
  eig &lt;- eigen(predictor_cor)

  lambda &lt;- eig$vectors %*%
    diag(sqrt(pmax(eig$values, 0))) %*%
    t(eig$vectors)

  beta_orthogonal &lt;- solve(lambda, outcome_cor)
  weights &lt;- as.vector((lambda^2) %*% (beta_orthogonal^2))

  setNames(weights, predictors)
}


For the linear methods, I fit satisfaction as a continuous outcome. For the random forest, I treat satisfaction as a five-class outcome and use impurity importance from ranger, which corresponds to mean decrease in Gini impurity for classification trees.


